/* IDO 7.1 NCC (C++) EXACT donor for gl_func_000454C4 (0x7EC / 507 words), agent-c run 160 lift, agent-c run 240 exact.
 * The light setup: `void Obj::setLights(Ctx *c, f32 *s, f32 k)` (renamed to gl_func_000454C4 with objcopy) fills a
 * Lights record (Ambient + Light[4], 0x48 bytes) taken from the context's light pool with `&lp->buf[lp->count++]`,
 * the ambient colour from the 0x194 element scaled by s[] and clamped by k, then walks the 0x18C node list with a
 * by-value list iterator (`LIter`: cur / nxt in memory, the target's sp+0x3C / 0x40 pair) and emits one stock-gbi
 * gSPLight per lit element (macro form: gDma1p with _SHIFTL, the Gfx pointer `_g` per expansion is the target's s0),
 * then gSPLight(ambient, n + 1) + gSPNumLights, or the one-light default (ambient copied into l[0]).
 * The element flags are read volatile (the target re-loads +0xC4 for the second test). The cfe body was 63.85
 * (2020 bytes); this is 91.40 at 2032 bytes (target 2028). Residual: the 255.0f constant is held in fs1 for the
 * whole function (the target keeps it in f0 and rematerialises it after the loop's call: four words of frame / save
 * and every sp offset shifted by 8), the 0x03000000 gSPLight constant is hoisted into s5 (target `lui at` per site),
 * so n / s / rec / c sit one s-register lower than the target.
 * The direction bytes carry a folded `& 0xFF` (one ugen ring slot each, the 42F4C idiom): 91.40 -> 91.48.
 * agent-c run 193 (decode): the target issues all six colour loads (s[0..2], e->col[0..2]) before the first
 * colour store, which the per-component `cv = ..; l->col[i] = cv; l->colc[i] = cv;` form cannot give (the Light
 * byte stores may alias the float loads); the three products are computed first into c0 / c1 / c2 and stored
 * after (colc[0] first, as the target's schedule), and the bb split sits after dir[0] too: 91.71 -> 95.72
 * report, 2032 -> 2020 bytes (target 2028: moved past it, flagged; the remaining words are the hoisted
 * 0x03000000 / 255.0f constants and the fs1 save listed above).
 * agent-g run 216: one more bb (`if (1) {}` after the last packet) drops both hoisted constants; no named `Light *l`
 * (every store through `rec->l[n]`, the target's v0 base for the dir bytes too), `n` declared before the iterator
 * (iterator at sp+60 / 64, frame 88) and plain direction bytes without the `& 0xFF`: 2020 -> 2028 bytes = target,
 * the body lines up word-for-word up to registers (six s-registers). The final bb lever as `if (rec) {}` (an
 * emission-free rec reference) breaks the rec / c adjsave tie (3.2 / 3.2, c won on bitpos) so rec takes s4 and c
 * s5 as in the target: 98.28 -> 98.66. The iterator tests the member it copied from (`cur = nxt; if (nxt)`):
 * `cur` is then no register candidate (it was LR {640|1} in v0), the latch value stays a ring temp (t7, store-
 * forwarded across the branch) and the whole t-register ring lines up: 98.66 -> 99.92. The gSPNumLights clamp
 * shared edg's int temp with the post-increment counts (v1); the clamp in a named `m` assigned in the same full
 * expression as c->next() and the w0 store gets its own LR (v0, the w0 store stays in the bgtz delay slot):
 * 99.92 -> 99.95. Residual: e copy-propagated as the inline return temp a3 into the second flags test and the
 * colour loads (five words; target a2).
 * agent-g run 217: the copy-propagation of e into the inline's pooled return temp stops at the first bb whose
 * block also redefines that edg temp (the gSPLight block's c->next()); with the bb split BEFORE dir[0] the dir
 * block holds c->next() and dir[0] reads e (a2) as in the target: 99.95 -> 99.96 (four words left).
 * agent-c run 240 (EXACT, 99.96 -> 100): the nested pool hold `(it.me()->me(), e->flags & 2)` stops the
 * propagation so the second test and the colour loads read e (body word-for-word up to registers, but e's
 * adjsave rises 13.7 -> 27 and it takes a1 ahead of c2; the return / dl pool temp then takes v1). e is 0 after
 * the loop, so post-loop reads of it are well defined: one folded `+ 0 * (int)e` in the n path's gSPLight count
 * and `if (e) {}` / folded reads in the default path (before its first call) add low-weight ref units that drop
 * e below c2 (16.6 -> 13.8), and the extra bb units split the pool temp so the count temp takes v1 first.
 * The four 0x34458 calls go through gl_454c4_c34458 (pinned 0: the target's blank USO jal words). */
typedef float f32; typedef unsigned int u32; typedef int s32; typedef unsigned char u8; typedef signed char s8;
extern "C" {
u32 gl_454c4_c34458(...);
}
struct Gfx { u32 w0, w1; };
struct DLHead { Gfx *buf; int count; };
struct Light { u8 col[3]; char p3; u8 colc[3]; char p7; s8 dir[3]; char pb; int pc; };
struct Ambient { u8 col[3]; char p3; u8 colc[3]; char p7; };
struct Lights { Ambient a; Light l[4]; };
struct LPool { Lights *buf; int count; };
struct Ctx {
    char pad[0xC];
    DLHead *dl;
    char pad10[0x2C - 0x10];
    LPool *lp;
    Gfx *next() { return &dl->buf[dl->count++]; }
    Lights *lights() { return &lp->buf[lp->count++]; }
};
#define _SHIFTL(v, s, w) (((u32)(v) & ((1 << (w)) - 1)) << (s))
#define gDma1p(pkt, c, s, l, p) { Gfx *_g = (Gfx *)(pkt); _g->w0 = (_SHIFTL((c), 24, 8) | _SHIFTL((p), 16, 8) | _SHIFTL((l), 0, 16)); _g->w1 = (u32)(s); }
#define gSPLight(pkt, l, n) gDma1p((pkt), 0x03, (l), sizeof(Light), ((n) - 1) * 2 + 0x86)
#define NUML(n) (((n) + 1) * 32 + 0x80000000)
#define gMoveWd(pkt, index, offset, data) { Gfx *_g = (Gfx *)(pkt); _g->w0 = (_SHIFTL(0xBC, 24, 8) | _SHIFTL((offset), 8, 16) | _SHIFTL((index), 0, 8)); _g->w1 = (u32)(data); }
#define gSPNumLights(pkt, n) gMoveWd(pkt, 2, 0, NUML(n))
#define MIN(a, b) ((a) < (b) ? (a) : (b))
struct LElem { char pad[0xC4]; volatile int flags; char padc8[0xE4 - 0xC8]; f32 dir[3]; char padf0[0xFC - 0xF0]; f32 col[3]; };
struct Node { LElem *data; Node *next; };
struct LIter {
    Node *cur;
    Node *nxt;
    LIter(Node *h) { nxt = h; }
    LIter *me() { return this; }
    LElem *next() { cur = nxt; if (nxt) { nxt = cur->next; return cur->data; } return 0; }
};
struct Obj {
    char pad[0x18C]; Node *lights; char pad190[4]; LElem *amb;
    void setLights(Ctx *c, f32 *s, f32 k);
};
void Obj::setLights(Ctx *c, f32 *s, f32 k) {
    Lights *rec = c->lights();
    u32 r = (u32)(amb->col[0] * s[0] * 255.0f) & 0xFF;
    u32 g = (u32)(amb->col[1] * s[1] * 255.0f) & 0xFF;
    u32 b = (u32)(amb->col[2] * s[2] * 255.0f) & 0xFF;
    if (k != 1.0) {
        r = (u32)MIN(r * k, 255.0f) & 0xFF;
        g = (u32)MIN(g * k, 255.0f) & 0xFF;
        b = (u32)MIN(b * k, 255.0f) & 0xFF;
    }
    rec->a.col[0] = r; rec->a.col[1] = g; rec->a.col[2] = b;
    rec->a.colc[0] = r; rec->a.colc[1] = g; rec->a.colc[2] = b;
    int n = 0;
    LIter it(lights);
    LElem *e;
    while ((e = it.next()) != 0) {
        if (!(e->flags & 0x80) && (it.me()->me(), e->flags & 2)) {
            s32 c0 = (s32)(s[0] * e->col[0] * 255.0f);
            s32 c1 = (s32)(s[1] * e->col[1] * 255.0f);
            s32 c2 = (s32)(s[2] * e->col[2] * 255.0f);
            rec->l[n].colc[0] = c0; rec->l[n].col[0] = c0;
            rec->l[n].col[1] = c1; rec->l[n].colc[1] = c1;
            rec->l[n].col[2] = c2; rec->l[n].colc[2] = c2;
            if (1) {}
            rec->l[n].dir[0] = (s32)(e->dir[0] * 120.0f);
            rec->l[n].dir[1] = (s32)(e->dir[1] * 120.0f);
            rec->l[n].dir[2] = (s32)(e->dir[2] * 120.0f);
            gSPLight(c->next(), gl_454c4_c34458(&rec->l[n]), n + 1);
            n++; if (1) {}
        }
    }
    if (n != 0) {
        gSPLight(c->next(), gl_454c4_c34458(&rec->a), n + 1 + 0 * (int)e);
        { Gfx *_g; int m; _g = c->next(), _g->w0 = (_SHIFTL(0xBC, 24, 8) | _SHIFTL(0, 8, 16) | _SHIFTL(2, 0, 8)), m = n <= 0 ? 1 : n; _g->w1 = NUML(m); }
        return;
    }
    if (e) {}
    rec->l[0].col[0] = rec->a.col[0];
    rec->l[0].col[1] = rec->a.col[1];
    rec->l[0].col[2] = rec->a.col[2];
    rec->l[0].colc[0] = rec->a.colc[0];
    if (e) {}
    rec->l[0].colc[1] = rec->a.colc[1];
    if (e) {}
    rec->l[0].colc[2] = rec->a.colc[2] + 0 * (int)e;
    gSPLight(c->next(), gl_454c4_c34458(&rec->l[0]), 1);
    gSPLight(c->next(), gl_454c4_c34458(&rec->a), 2);
    gSPNumLights(c->next(), 1); if (rec) {}
}
